"""
Alert Manager Module.
Processes detection results, assigns severity, deduplicates, and logs security incidents.
"""

from typing import Dict, Any, List, Optional
import time


class AlertManager:
    """Manages security notifications generated by the intrusion detector."""

    SEVERITY_MAPPING = {
        "Normal": "INFO",
        "DoS_Publish_Flood": "CRITICAL",
        "Port_Scan": "MEDIUM",
        "Brute_Force": "HIGH",
        "Malformed_Packet": "HIGH",
        "Unknown": "MEDIUM"
    }

    def __init__(self, suppression_window_seconds: float = 2.0):
        self.suppression_window = suppression_window_seconds
        self.recent_alerts: Dict[str, float] = {}
        self.history: List[Dict[str, Any]] = []

    def process_prediction(
        self,
        prediction: Dict[str, Any],
        device_id: str = "iot-device-unknown",
        source_ip: str = "10.0.0.1",
        topic: str = "campus/telemetry"
    ) -> Optional[Dict[str, Any]]:
        """
        Processes prediction dict. If an attack is detected and not suppressed, generates an alert record.
        """
        if not prediction.get("is_anomaly", False):
            return None

        attack_type = prediction.get("attack_type", "Unknown")
        now = time.time()
        dedup_key = f"{device_id}:{source_ip}:{attack_type}"

        # Duplicate suppression check
        last_seen = self.recent_alerts.get(dedup_key, 0.0)
        if (now - last_seen) < self.suppression_window:
            return None

        self.recent_alerts[dedup_key] = now
        severity = self.SEVERITY_MAPPING.get(attack_type, "MEDIUM")

        alert = {
            "alert_id": f"ALT-{int(now * 1000) % 1000000:06d}",
            "timestamp": now,
            "device_id": device_id,
            "source_ip": source_ip,
            "topic": topic,
            "attack_type": attack_type,
            "severity": severity,
            "confidence": prediction.get("confidence", 0.0),
            "attack_probability": prediction.get("attack_probability", 0.0),
            "action_recommended": self._get_recommendation(attack_type)
        }
        self.history.append(alert)
        return alert

    def _get_recommendation(self, attack_type: str) -> str:
        recommendations = {
            "DoS_Publish_Flood": "Throttle broker client rate & apply temporary IP ban.",
            "Port_Scan": "Monitor IP address & verify firewall ACL rules.",
            "Brute_Force": "Isolate MQTT client ID and force credential reset.",
            "Malformed_Packet": "Drop invalid packets and inspect broker parsing logs."
        }
        return recommendations.get(attack_type, "Inspect traffic flow manually.")
